SELECT analytics_order_facts.category, SUM(analytics_order_facts.contribution_margin) / CAST(NULLIF(SUM(analytics_order_facts.net_revenue), 0) AS DECIMAL) AS contribution_margin_pct FROM analytics_order_facts WHERE analytics_order_facts.year = 2025 AND analytics_order_facts.month = 4 AND analytics_order_facts.region = 'North' AND analytics_order_facts.channel = 'online' AND analytics_order_facts.customer_segment = 'small_business' GROUP BY analytics_order_facts.category ORDER BY contribution_margin_pct DESC, analytics_order_facts.category ASC LIMIT 12
